#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/controls/scrollable_control/container_control/container_control.hpp"
#include "gui_forms/layout/block_flow_solver/block_flow_solver.hpp"
#include "gui_forms/layout/style/layout_style.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// BlockPanel's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/block_panel.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// The line boxes' inline alignment; start by default. justify is not admitted (std::invalid_argument).
template <typename Declaring>
struct BlockPanelTextAlignCapability {
    PropertyCell<TextAlignment, BlockPanelTextAlignCapability<Declaring>> text_align{TextAlignment::start};

    static void assign(BlockPanelTextAlignCapability& capability, TextAlignment incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.text_align), incoming);
        if (!capability.text_align.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.text_align));
    }
};

// The strut every line box starts with (CSS 2.1 section 10.8.1), used as given; empty takes the font's line-height: normal line box at the effective text scale (used_line_strut). Its values must be finite and nonnegative (std::invalid_argument).
template <typename Declaring>
struct BlockPanelLineStrutCapability {
    PropertyCell<std::optional<LineStrut>, BlockPanelLineStrutCapability<Declaring>> line_strut{};

    static void assign(BlockPanelLineStrutCapability& capability, std::optional<LineStrut> incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.line_strut), incoming);
        if (!capability.line_strut.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.line_strut));
    }
};

// The panel's own font for the strut; empty takes the theme's field typography (resolved_font). Must be a valid font specification (std::invalid_argument).
template <typename Declaring>
struct BlockPanelFontCapability {
    PropertyCell<std::optional<FontSpec>, BlockPanelFontCapability<Declaring>> font{};

    static void assign(BlockPanelFontCapability& capability, std::optional<FontSpec> incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.font), incoming);
        if (!capability.font.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.font));
    }
};

// Every BlockPanel capability, in the order the declaring class takes them.
template <typename Declaring>
struct BlockPanelCapabilities : public BlockPanelTextAlignCapability<Declaring>,
                                public BlockPanelLineStrutCapability<Declaring>,
                                public BlockPanelFontCapability<Declaring> {};

} // namespace gui_forms
